<?php

declare(strict_types=1);
use Illuminate\Container\Container;use Illuminate\Database\Capsule\Manager;use Illuminate\Database\Connectors\ConnectionFactory;use Tenant\Data\{BindingExpectation,BindingVerificationInput};use Tenant\Postgres\{Admission};use Tenant\Postgres\Data\{PhysicalAccess,ResourceSnapshot,TemplateTrust};use Tenant\Postgres\Internal\{PostgresBindingVerifier,ProvisionJournal,ReplayableProvision,ResourceSnapshotReader};use Tenant\Postgres\Internal\Database\{SchemaCatalogueSerializer,TemplateIntegrityLock,TemplateIntegrityVerifier};
require_once __DIR__.'/public-errors-autoload.php';
require getenv('P41_AUTOLOAD');spl_autoload_register(static function(string $class):void{foreach(['Tenant\\Postgres\\'=>__DIR__.'/../../packages/tenant-postgres/src/','Tenant\\'=>__DIR__.'/../../packages/tenant/src/'] as $prefix=>$root)if(str_starts_with($class,$prefix)){require $root.str_replace('\\','/',substr($class,strlen($prefix))).'.php';return;}});
$run=getenv('P41_RUN_ID');$base='tenant_p41_'.$run;$runtime=$base.'_runtime';if(!preg_match('/^[a-f0-9]{12}$/D',$run)||getenv('P41_DB')!==$base.'_central_test'||getenv('P41_HOST')!=='127.0.0.1'||getenv('P41_USER')!==$base.'_admin')throw new RuntimeException('Unsafe target');
$app=new Container;$db=new Manager($app);$cfg=['driver'=>'pgsql','host'=>getenv('P41_HOST'),'port'=>getenv('P41_PORT'),'database'=>getenv('P41_DB'),'username'=>getenv('P41_USER'),'password'=>getenv('P41_PASSWORD'),'charset'=>'utf8','prefix'=>'','schema'=>'public'];$db->addConnection($cfg,'lab');$c=$db->getConnection('lab');$factory=new ConnectionFactory($app);$t=json_decode(file_get_contents(getenv('P41_TRUST')),true,flags:JSON_THROW_ON_ERROR);$template='12121212-1212-4212-8212-121212121212';$trust=new TemplateTrust([$template=>['payload'=>$t['payload'],'signature'=>$t['signature'],'trusted_key_id'=>'lab']],['lab'=>$t['key']]);$integrity=new TemplateIntegrityVerifier('lab',new SchemaCatalogueSerializer,new TemplateIntegrityLock,$trust,$db->getDatabaseManager(),$factory);
$routeFor=static function(object $row)use($cfg,$runtime):array{$r=$cfg;$r['database']=$row->database_name;$r['username']=$runtime;$r['password']=getenv('P41_RUNTIME_PASSWORD');return $r;};$binding=new PostgresBindingVerifier($c,$routeFor,maintenance:true);$verify=static function(ResourceSnapshot $s)use($c,$binding,$routeFor):void{$r=$c->table('tenant_pg_resources')->where('resource_ref',$s->resourceRef)->first();$binding->verify(new BindingVerificationInput(new BindingExpectation($s->resourceRef,$s->incarnation,$r->route_revision),new PhysicalAccess($routeFor($r))));};
