$row=$c->table('tenant_pg_provision_attempts')->where('host_intent_ref','host:pool')->where('status','succeeded')->first();if($row===null)throw new RuntimeException('Missing pool producer');$snapshot=$reader->capture($row->resource_ref,$row->incarnation);$result=$pipeline->run($row->id,$snapshot,$allow);if($result->operationId!==$row->id||$result->status!=='succeeded')throw new RuntimeException('Pipeline failed to replay');
try{$pipeline->run($row->id,new ResourceSnapshot($snapshot->resourceRef,'incarnation:wrong',$snapshot->templateVersion,$snapshot->clusterId,$snapshot->databaseName),$allow);throw new RuntimeException('Stale incarnation accepted');}catch(\Tenant\Postgres\Exceptions\ClaimConflict){}
$unknown=$c->table('tenant_pg_provision_attempts')->where('host_intent_ref','host:late')->first();$late=$reader->capture($unknown->resource_ref,$unknown->incarnation);$res=$pipeline->run($unknown->id,$late,$allow);if($res->status!=='unknown'||$res->operationId!==$unknown->id)throw new RuntimeException('Unknown operation changed');
echo json_encode(['status'=>'passed','scope'=>'actual replay pipeline, original snapshot, stale incarnation and unknown refusal','operation'=>$row->id,'unknown'=>$unknown->id],JSON_THROW_ON_ERROR),"\n";
